/// <summary>
/// Initializes a <c>SalesParmTable</c> record.
/// </summary>
/// <param name = "_salesTable">A <c>SalesTable</c> record used to initialize the <c>SalesParmTable</c>.</param>
/// <param name = "_salesLine">A <c>SalesLine</c> record used to initialize the <c>SalesParmTable</c>.</param>
/// <param name = "_tableRefId">Trade line reference used to initialize the <c>SalesParmTable</c>.</param>
/// <param name = "_postingProfile">Customer posting profile.</param>
/// <param name = "_inventProfileType">Inventory profile type.</param>
/// <param name = "_inventOwnerId">Inventory owner ID.</param>
/// <param name = "_mcrPackingBoxName">The packing box name.</param>
/// <returns>The initialized <c>SalesParmTableRecord</c>.</returns>
protected SalesParmTable initParmTable(SalesTable           _salesTable,
                                       Common               _salesLine,
                                       TradeLineRefId       _tableRefId,
                                       CustPostingProfile   _postingProfile,
                                       InventProfileType_RU _inventProfileType,
                                       InventOwnerId_RU     _inventOwnerId,
                                       MCRPackingBoxName     _mcrPackingBoxName)
{
    SalesParmTable avaSalesParmTable = next initParmTable(_salesTable, _salesLine, _tableRefId, _postingProfile, _inventProfileType, _inventOwnerId, _mcrPackingBoxName);

    avaSalesParmTable.AVAEmailInvoice   = _salesTable.Email;

    return avaSalesParmTable;
}

/// <summary>
/// Extension of method updateParmTable
/// </summary>
/// <param name = "_salesParmTable">SalesParmTable</param>
/// <param name = "_salesTable">SalesTable</param>
protected void  updateParmTable(SalesParmTable    _salesParmTable,
                                SalesTable        _salesTable)
{
    next updateParmTable(_salesParmTable, _salesTable);

    _salesParmTable.AVAEmailInvoice = _salesTable.Email;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <returns>boolean</returns>
protected boolean mayJournalBePosted(Common _salesTable)
{
    SalesTable tmpSalesTable = _salesTable as SalesTable;
    boolean checkCRLOK = true;
    boolean ok  = next mayJournalBePosted(_salesTable);

    if (ok)
    {
        if (custParameters::find().salesCheckCreditOnHeader())
        {
            CustCreditLimit custCreditLimit = CustCreditLimit::construct(tmpSalesTable, null);

            checkCRLOK = custCreditLimit.check();

            //tmpSalesTable.checkAgainstCreditLimit();
        }

        if (!checkCRLOK)
        {
            if (Box::yesNo(strFmt("@NDX:NXACRLCheck", tmpSalesTable.SalesId), DialogButton::Yes) == DialogButton::No)
            {
                ok = false;
                throw error("@NDX:NDXEmptyEntry");
            }
        }
    }
    return ok;
}
